import {materials} from '../../core/index.js';import {printedArtwork} from '../../modeling/artwork.js';import {roundedRect,mesh,solid} from './geometry.js';import {spec} from './dimensions.js';import {casing,fixing} from './shell.js';import {grove} from './connectors.js';import {electronics} from './electronics.js';
const urls={front:new URL('./artwork/front.png',import.meta.url).href,rear:new URL('./artwork/rear.png',import.meta.url).href};
export function buildRFID(host){const shell=casing(host),board=electronics(host),input=grove(host),fastener=fixing(host),films={},ink=[];for(const id of['front','rear']){const cfg=spec[id+'Film'],film=mesh(host.body,solid(roundedRect(...cfg.size,.2),cfg.thicknessMm),materials.plastic(id==='front'?0xbcb9af:0xc9c5ba,{roughness:.78,metalness:.16}),cfg.position,'Original U031 actual '+id+' manufacturer adhesive film');film.userData={role:'physical-label-substrate',thicknessMm:cfg.thicknessMm,registrationInferred:true};films[id]=film;ink.push(...(printedArtwork(host,{target:film,url:urls[id],size:cfg.size,position:id==='front'?[cfg.position[0],cfg.position[1],cfg.position[2]+cfg.thicknessMm]:cfg.position,face:id==='front'?'front':'back',depth:.16,name:'Original U031 '+id+' readable code-redrawn ink',artworkKind:'reference-redraw'})??[]));}host.rfidAssembly={frame:shell.rear.parent,shell,board,input,fixing:fastener,films,ink};host.unitStickers=ink;}
